<?php
require_once 'config/database.php';require_once 'includes/auth.php';
$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']);$desc=trim($_POST['description']);$cat=(int)$_POST['category_id'];$loc=trim($_POST['location']);$min=$_POST['budget_min']===''?null:(float)$_POST['budget_min'];$max=$_POST['budget_max']===''?null:(float)$_POST['budget_max'];$currency=$_POST['currency'];if(!$title||!$desc||!$cat)$error='Please complete the required fields.';else{$s=$pdo->prepare("INSERT INTO jobs(user_id,category_id,title,description,location,budget_min,budget_max,currency) VALUES(?,?,?,?,?,?,?,?)");$s->execute([current_user_id(),$cat,$title,$desc,$loc,$min,$max,$currency]);flash('success','Your job has been posted.');redirect('job.php?id='.$pdo->lastInsertId());}}
$pageTitle='Post a job';include 'includes/header.php';?>
<div class="section"><div class="container narrow"><div class="form-card"><span class="eyebrow">HIRE SOMEONE</span><h1>Post a job or gig</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Job title<input name="title" required placeholder="e.g. Need a website for my restaurant"></label><label>Category<select name="category_id" required><option value="">Choose</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Describe what you need<textarea name="description" rows="7" required placeholder="Explain the work, requirements, timing and anything applicants should know."></textarea></label><label>Location<input name="location" value="Kampala" placeholder="City / area or Remote"></label><div class="form-row"><label>Minimum budget<input type="number" name="budget_min" min="0"></label><label>Maximum budget<input type="number" name="budget_max" min="0"></label></div><label>Currency<select name="currency"><option>UGX</option><option>KES</option><option>TZS</option><option>RWF</option><option>USD</option></select></label><button class="btn">Publish job</button></form></div></div></div><?php include 'includes/footer.php';?>
